-- Retrieved 2026-09-12 from FishBase summary pages, GBIF IUCN
-- categories, and OBIS occurrence records. Missing fields stay NULL.

BEGIN;

INSERT INTO data_source (data_source_id, source_key, name, owner, type, homepage_url, license, active)
SELECT
  suka_uuid5('data_source:' || v.source_key),
  v.source_key, v.name, v.owner, v.type, v.homepage_url, v.license, TRUE
FROM (VALUES
  ('fishbase', 'FishBase', 'Froese & Pauly / FishBase', 'BIODIVERSITY',
   'https://www.fishbase.se', 'FishBase citation required.'),
  ('obis', 'OBIS', 'Ocean Biodiversity Information System', 'BIODIVERSITY',
   'https://obis.org', 'Mostly CC BY 4.0; verify per-dataset licence.'),
  ('iucn_redlist', 'IUCN Red List of Threatened Species', 'IUCN', 'BIODIVERSITY',
   'https://www.iucnredlist.org', 'IUCN Red List categories via GBIF/FishBase.'),
  ('mybis', 'MyBIS', 'Malaysia Biodiversity Information System', 'BIODIVERSITY',
   'https://www.mybis.gov.my', 'No public API on file. National status stays unavailable.'),
  ('reef_check', 'Reef Check', 'Reef Check Malaysia / Reef Check', 'BIODIVERSITY',
   'https://www.reefcheck.org.my', 'No public machine-readable extract on file.')
) AS v(source_key, name, owner, type, homepage_url, license)
ON CONFLICT (data_source_id) DO UPDATE SET
  name = EXCLUDED.name,
  homepage_url = EXCLUDED.homepage_url,
  license = EXCLUDED.license,
  active = EXCLUDED.active;

INSERT INTO source_snapshot (
  source_snapshot_id, data_source_id, version_label,
  source_period_start, source_period_end, retrieved_at, collection_method, manifest, notes
)
SELECT
  suka_uuid5('source_snapshot:' || v.source_key || ':' || v.version_label),
  suka_uuid5('data_source:' || v.source_key),
  v.version_label, NULL, NULL, TIMESTAMPTZ '2026-09-12 13:20:00+00',
  'OFFICIAL_DOWNLOAD'::collection_method_enum,
  '{"tables":["species","occurrence"]}'::jsonb,
  v.notes
FROM (VALUES
  ('fishbase', '2026-09-12', 'FishBase summary pages retrieved 2026-09-12.'),
  ('obis', '2026-09-12', 'OBIS API v3 occurrence sample, up to 40 points per species.'),
  ('iucn_redlist', '2026-09-12', 'IUCN category via GBIF species match.')
) AS v(source_key, version_label, notes)
ON CONFLICT (source_snapshot_id) DO UPDATE SET
  notes = EXCLUDED.notes,
  retrieved_at = EXCLUDED.retrieved_at;

INSERT INTO biodiversity_profile (
  seafood_item_id, habitat_group, depth_shallow_m, depth_deep_m,
  ecological_role, iucn_category, iucn_label, iucn_url, fishbase_url,
  retrieved_at, source_snapshot_id
)
SELECT
  v.seafood_item_id, v.habitat_group, v.depth_shallow_m, v.depth_deep_m,
  v.ecological_role, v.iucn_category, v.iucn_label, v.iucn_url, v.fishbase_url,
  v.retrieved_at, v.source_snapshot_id
FROM (VALUES
  (suka_uuid5('seafood_item:SF001'), 'pelagic-neritic', 20.0, 90.0, 'Adults occur in coastal bays, harbors and deep lagoons, usually in some turbid plankton-rich waters. Feed on phytoplankton (diatoms) and small zooplankton (cladocerans, ostracods, larval polychaetes, etc.) .', 'LC', 'Least Concern', 'https://www.iucnredlist.org/search?query=Rastrelliger%20kanagurta', 'https://www.fishbase.se/summary/Rastrelliger-kanagurta.html', TIMESTAMPTZ '2026-09-12 13:20:00+00', suka_uuid5('source_snapshot:fishbase:2026-09-12')),
  (suka_uuid5('seafood_item:SF002'), 'reef-associated', 15.0, 105.0, 'Feed on zooplankton .', 'LC', 'Least Concern', 'https://www.iucnredlist.org/search?query=Parastromateus%20niger', 'https://www.fishbase.se/summary/Parastromateus-niger.html', TIMESTAMPTZ '2026-09-12 13:20:00+00', suka_uuid5('source_snapshot:fishbase:2026-09-12')),
  (suka_uuid5('seafood_item:SF003'), 'reef-associated', 5.0, 180.0, 'Adults occur in the vicinity of coral or rocky reefs , often over adjacent sand flats and gravel patches . Also trawled in deeper water on relatively flat bottoms.', 'LC', 'Least Concern', 'https://www.iucnredlist.org/search?query=Lutjanus%20sebae', 'https://www.fishbase.se/summary/Lutjanus-sebae.html', TIMESTAMPTZ '2026-09-12 13:20:00+00', suka_uuid5('source_snapshot:fishbase:2026-09-12')),
  (suka_uuid5('seafood_item:SF004'), 'benthopelagic', 0.0, 20.0, 'They feed mainly on phytoplankton or benthic algae.', 'LC', 'Least Concern', 'https://www.iucnredlist.org/search?query=Oreochromis%20niloticus', 'https://www.fishbase.se/summary/Oreochromis-niloticus.html', TIMESTAMPTZ '2026-09-12 13:20:00+00', suka_uuid5('source_snapshot:fishbase:2026-09-12')),
  (suka_uuid5('seafood_item:SF005'), 'reef-associated', 1.0, 100.0, 'Feed on small fishes, shrimps, and crabs.', 'LC', 'Least Concern', 'https://www.iucnredlist.org/search?query=Epinephelus%20coioides', 'https://www.fishbase.se/summary/Epinephelus-coioides.html', TIMESTAMPTZ '2026-09-12 13:20:00+00', suka_uuid5('source_snapshot:fishbase:2026-09-12')),
  (suka_uuid5('seafood_item:SF006'), 'benthopelagic', 5.0, 110.0, 'Adults feed on ctenophores, salps, medusae, and other zooplankton groups.', 'NE', 'Not Evaluated', 'https://www.iucnredlist.org/search?query=Pampus%20argenteus', 'https://www.fishbase.se/summary/Pampus-argenteus.html', TIMESTAMPTZ '2026-09-12 13:20:00+00', suka_uuid5('source_snapshot:fishbase:2026-09-12')),
  (suka_uuid5('seafood_item:SF007'), 'reef-associated', 20.0, 100.0, 'They feed mainly on fishes .', 'LC', 'Least Concern', 'https://www.iucnredlist.org/search?query=Megalaspis%20cordyla', 'https://www.fishbase.se/summary/Megalaspis-cordyla.html', TIMESTAMPTZ '2026-09-12 13:20:00+00', suka_uuid5('source_snapshot:fishbase:2026-09-12')),
  (suka_uuid5('seafood_item:SF008'), 'reef-associated', 0.0, 80.0, 'Feed on fishes and benthic invertebrates including shrimps, crabs and cephalopods.', 'LC', 'Least Concern', 'https://www.iucnredlist.org/search?query=Lutjanus%20johnii', 'https://www.fishbase.se/summary/Lutjanus-johnii.html', TIMESTAMPTZ '2026-09-12 13:20:00+00', suka_uuid5('source_snapshot:fishbase:2026-09-12')),
  (suka_uuid5('seafood_item:SF009'), 'demersal', 5.0, 80.0, 'Feeds mainly on small fishes, crustaceans, mollusks (mainly cephalopods), polychaetes and echinoderms.', 'LC', 'Least Concern', 'https://www.iucnredlist.org/search?query=Nemipterus%20japonicus', 'https://www.fishbase.se/summary/Nemipterus-japonicus.html', TIMESTAMPTZ '2026-09-12 13:20:00+00', suka_uuid5('source_snapshot:fishbase:2026-09-12')),
  (suka_uuid5('seafood_item:SF010'), 'pelagic-neritic', NULL, NULL, 'Feed mainly on small invertebrates, shrimps and copepods.', 'LC', 'Least Concern', 'https://www.iucnredlist.org/search?query=Alepes%20melanoptera', 'https://www.fishbase.se/summary/Alepes-melanoptera.html', TIMESTAMPTZ '2026-09-12 13:20:00+00', suka_uuid5('source_snapshot:fishbase:2026-09-12')),
  (suka_uuid5('seafood_item:SF011'), 'reef-associated', 1.0, 50.0, 'Ostracods, gastropods and euphausiids are common prey but small fish are also taken.', 'LC', 'Least Concern', 'https://www.iucnredlist.org/search?query=Selaroides%20leptolepis', 'https://www.fishbase.se/summary/Selaroides-leptolepis.html', TIMESTAMPTZ '2026-09-12 13:20:00+00', suka_uuid5('source_snapshot:fishbase:2026-09-12')),
  (suka_uuid5('seafood_item:SF012'), 'pelagic-neritic', 10.0, 70.0, 'Feed primarily on small fishes like anchovies, clupeids, carangids, also squids and penaeoid shrimps.', 'NT', 'Near Threatened', 'https://www.iucnredlist.org/search?query=Scomberomorus%20commerson', 'https://www.fishbase.se/summary/Scomberomorus-commerson.html', TIMESTAMPTZ '2026-09-12 13:20:00+00', suka_uuid5('source_snapshot:fishbase:2026-09-12')),
  (suka_uuid5('seafood_item:SF014'), 'demersal', 10.0, 40.0, 'Feed on fishes and crustaceans.', 'LC', 'Least Concern', 'https://www.iucnredlist.org/search?query=Lates%20calcarifer', 'https://www.fishbase.se/summary/Lates-calcarifer.html', TIMESTAMPTZ '2026-09-12 13:20:00+00', suka_uuid5('source_snapshot:fishbase:2026-09-12')),
  (suka_uuid5('seafood_item:SF015'), 'pelagic-neritic', 0.0, 200.0, 'A highly opportunistic predator feeding indiscriminately on small fishes, especially on clupeoids and atherinids; also on squids, crustaceans and zooplankton.', 'LC', 'Least Concern', 'https://www.iucnredlist.org/search?query=Euthynnus%20affinis', 'https://www.fishbase.se/summary/Euthynnus-affinis.html', TIMESTAMPTZ '2026-09-12 13:20:00+00', suka_uuid5('source_snapshot:fishbase:2026-09-12'))
) AS v(
  seafood_item_id, habitat_group, depth_shallow_m, depth_deep_m,
  ecological_role, iucn_category, iucn_label, iucn_url, fishbase_url,
  retrieved_at, source_snapshot_id
)
WHERE EXISTS (SELECT 1 FROM seafood_item s WHERE s.seafood_item_id = v.seafood_item_id)
ON CONFLICT (seafood_item_id) DO UPDATE SET
  habitat_group = EXCLUDED.habitat_group,
  depth_shallow_m = EXCLUDED.depth_shallow_m,
  depth_deep_m = EXCLUDED.depth_deep_m,
  ecological_role = EXCLUDED.ecological_role,
  iucn_category = EXCLUDED.iucn_category,
  iucn_label = EXCLUDED.iucn_label,
  iucn_url = EXCLUDED.iucn_url,
  fishbase_url = EXCLUDED.fishbase_url,
  retrieved_at = EXCLUDED.retrieved_at,
  source_snapshot_id = EXCLUDED.source_snapshot_id;

